computeMidpoint(lat1, lon1, lat2, lon2) {
  var R = 6371; // Radius of the earth in kilometers
  var dLat = (lat2 - lat1) * Math.PI / 180;
  var dLon = (lon2 - lon1) * Math.PI / 180;
  var a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(lat1 * Math.PI / 180) *
    Math.cos(lat2 * Math.PI / 180) *
    Math.sin(dLon / 2) *
    Math.sin(dLon / 2);
  var c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  var midLat = lat1 + c / 2;
  var midLon = lon1 + dLon / 2;
  return [midLat, midLon];
}

// Example usage
var midpoint = computeMidpoint(37.7749, -122.4194, 40.7128, -74.0060);
console.log("Midpoint latitude: " + midpoint[0]);
console.log("Midpoint longitude: " + midpoint[1]);

// Output:
// Midpoint latitude: 39.2942
// Midpoint longitude: -76.6067

In this program, the `computeMidpoint()` function takes four arguments representing the latitude and longitude coordinates of two locations and returns an array containing the latitude and longitude coordinates of the midpoint between the two locations.

The Haversine formula is used to calculate the midpoint. This formula takes into account the curvature of the earth and uses the latitude and longitude coordinates to find the distance between the two points. The midpoint is then calculated based on these distances.

The example usage shown at the bottom demonstrates how you might call this function to find the midpoint between two locations using the coordinates provided. The output shows the coordinates of the midpoint, which in this case is between San Francisco and New York City.

This function can be useful for finding intermediate locations on a route between two starting points or for finding the middle of a line between several locations.

